using System.Security.Cryptography;using System.Text;using System.Text.Json;using Microsoft.Extensions.Logging.Abstractions;using Microsoft.Extensions.Options;
using StockSyncAI.Api.Configuration;using StockSyncAI.Api.Database;using StockSyncAI.Api.DTOs;using StockSyncAI.Api.Models;using StockSyncAI.Api.Services;
namespace StockSyncAI.Tests.Services;
public sealed class InvoicePostingServiceTests:IDisposable
{
 private readonly string dir=Path.Combine(Path.GetTempPath(),$"stocksync-post-service-{Guid.NewGuid():N}");
 [Fact] public async Task SuccessfulPosting_IsAuthoritativeAndCannotRepeat()
 {var writer=new FakeWriter();var c=await Create(writer);var prepared=await c.Service.PrepareAsync(c.InvoiceId);var id=Guid.Parse(prepared.Readiness.PostingId!);var posted=await c.Service.PostAsync(c.InvoiceId,id,"POST TO POS");Assert.Equal(PostingStates.Posted,posted.Readiness.State);Assert.Equal(1,writer.Calls);await Assert.ThrowsAsync<PostingValidationException>(()=>c.Service.PostAsync(c.InvoiceId,id,"POST TO POS"));Assert.Equal(1,writer.Calls);}
 [Fact] public async Task ConfirmedRollback_IsRetryableButUnknownOutcomeIsBlocked()
 {var rollback=new FakeWriter{Error=new PosConfirmedRollbackException("rolled back")};var c=await Create(rollback);var p=await c.Service.PrepareAsync(c.InvoiceId);await Assert.ThrowsAsync<PosConfirmedRollbackException>(()=>c.Service.PostAsync(c.InvoiceId,Guid.Parse(p.Readiness.PostingId!),"POST TO POS"));var retry=await c.Service.GetStatusAsync(c.InvoiceId);Assert.Equal(PostingStates.FailedSafeToRetry,retry.Readiness.State);Assert.True(retry.Readiness.RetryEligible);Assert.True(retry.Readiness.CanPrepare);
  var unknown=new FakeWriter{Error=new PosOutcomeUnknownException("unknown")};var c2=await Create(unknown,"unknown");var p2=await c2.Service.PrepareAsync(c2.InvoiceId);await Assert.ThrowsAsync<PosOutcomeUnknownException>(()=>c2.Service.PostAsync(c2.InvoiceId,Guid.Parse(p2.Readiness.PostingId!),"POST TO POS"));var status=await c2.Service.GetStatusAsync(c2.InvoiceId);Assert.Equal(PostingStates.OutcomeUnknown,status.Readiness.State);Assert.False(status.Readiness.CanPrepare);}
 [Fact] public async Task DisabledOrUnverifiedSchema_BlocksBeforeWriter()
 {var writer=new FakeWriter();var c=await Create(writer,schemaValid:false);var status=await c.Service.GetStatusAsync(c.InvoiceId);Assert.False(status.Readiness.CanPrepare);Assert.Contains(status.Readiness.Blockers,x=>x.Contains("disabled",StringComparison.OrdinalIgnoreCase));await Assert.ThrowsAsync<PostingValidationException>(()=>c.Service.PrepareAsync(c.InvoiceId));Assert.Equal(0,writer.Calls);}
 [Fact] public async Task ConcurrentRequests_AllowOnlyOneWriter()
 {var writer=new BlockingWriter();var c=await Create(writer,"concurrent");var p=await c.Service.PrepareAsync(c.InvoiceId);var id=Guid.Parse(p.Readiness.PostingId!);var first=c.Service.PostAsync(c.InvoiceId,id,"POST TO POS");await writer.Started.Task;await Assert.ThrowsAsync<PostingConflictException>(()=>c.Service.PostAsync(c.InvoiceId,id,"POST TO POS"));writer.Release.SetResult();await first;Assert.Equal(1,writer.Calls);}
 [Fact] public async Task StaleReviewFingerprint_BlocksPreparation()
 {var c=await Create(new FakeWriter(),"stale");var extraction=await c.Extractions.GetAsync(c.InvoiceId);await c.Extractions.TryBeginAsync(c.InvoiceId,DateTimeOffset.UtcNow);var changed=InvoiceExtractionServiceTests.SampleData() with{InvoiceNumber=new("changed",null)};await c.Extractions.CompleteAsync(c.InvoiceId,InvoiceExtractionRecord.SucceededStatus,JsonSerializer.Serialize(changed,new JsonSerializerOptions(JsonSerializerDefaults.Web)),DateTimeOffset.UtcNow);var status=await c.Service.GetStatusAsync(c.InvoiceId);Assert.Contains(status.Readiness.Blockers,x=>x.Contains("latest",StringComparison.OrdinalIgnoreCase));}
 [Fact] public async Task Posting_RequiresExactServerSideConfirmation()
 {var writer=new FakeWriter();var c=await Create(writer,"confirmation");var p=await c.Service.PrepareAsync(c.InvoiceId);await Assert.ThrowsAsync<PostingValidationException>(()=>c.Service.PostAsync(c.InvoiceId,Guid.Parse(p.Readiness.PostingId!),"yes"));Assert.Equal(0,writer.Calls);}
 [Fact] public async Task CurrentVendorAndProductReferences_AreRevalidated()
 {var c=await Create(new FakeWriter(),"references");var review=(await c.Reviews.GetAsync(c.InvoiceId))!;await c.Reviews.SaveAsync(review with{SelectedVendorName="Removed Vendor"});var vendor=await c.Service.GetStatusAsync(c.InvoiceId);Assert.Contains(vendor.Readiness.Blockers,x=>x.Contains("vendor",StringComparison.OrdinalIgnoreCase));
  var line=Assert.Single(review.Lines) with{SelectedProductId="REMOVED"};await c.Reviews.SaveAsync(review with{Lines=[line]});var product=await c.Service.GetStatusAsync(c.InvoiceId);Assert.Contains(product.Readiness.Blockers,x=>x.Contains("no longer exists",StringComparison.OrdinalIgnoreCase));}
 [Fact] public async Task NewProductAndExpiryFields_AreValidatedByPreflight()
 {var c=await Create(new FakeWriter(),"new-product");var review=(await c.Reviews.GetAsync(c.InvoiceId))!;var line=Assert.Single(review.Lines) with{DecisionSource=ReviewDecisionSources.NewProductCandidate,SelectedProductId=null,NewProductName="Medicine",NewProductCategory="Missing",NewProductSellingPrice=null,ExpiryDate="tomorrow"};await c.Reviews.SaveAsync(review with{Lines=[line]});var status=await c.Service.GetStatusAsync(c.InvoiceId);Assert.Contains(status.Readiness.Blockers,x=>x.Contains("category",StringComparison.OrdinalIgnoreCase));Assert.Contains(status.Readiness.Blockers,x=>x.Contains("selling price",StringComparison.OrdinalIgnoreCase));Assert.Contains(status.Readiness.Blockers,x=>x.Contains("expiry",StringComparison.OrdinalIgnoreCase));}
 [Fact] public async Task ReviewEdit_InvalidatesPreparedSnapshot()
 {var c=await Create(new FakeWriter(),"edited");var prepared=await c.Service.PrepareAsync(c.InvoiceId);var oldId=Guid.Parse(prepared.Readiness.PostingId!);var review=(await c.Reviews.GetAsync(c.InvoiceId))!;var line=Assert.Single(review.Lines) with{NetLineAmount=600,PerUnitCost=15};await c.Reviews.SaveAsync(review with{Lines=[line],UpdatedUtc=DateTimeOffset.UtcNow});var status=await c.Service.GetStatusAsync(c.InvoiceId);Assert.Equal("NotPosted",status.Readiness.State);Assert.True(status.Readiness.CanPrepare);await Assert.ThrowsAsync<PostingConflictException>(()=>c.Service.PostAsync(c.InvoiceId,oldId,"POST TO POS"));}
 [Fact] public async Task UnexpectedWriterFailure_BecomesOutcomeUnknownAndBlocksRetry()
 {var writer=new FakeWriter{Error=new InvalidOperationException("connection lost")};var c=await Create(writer,"unexpected");var prepared=await c.Service.PrepareAsync(c.InvoiceId);await Assert.ThrowsAsync<PosOutcomeUnknownException>(()=>c.Service.PostAsync(c.InvoiceId,Guid.Parse(prepared.Readiness.PostingId!),"POST TO POS"));var status=await c.Service.GetStatusAsync(c.InvoiceId);Assert.Equal(PostingStates.OutcomeUnknown,status.Readiness.State);Assert.False(status.Readiness.CanPrepare);Assert.False(status.Readiness.CanPost);}
 [Fact] public async Task PosCommitWithLocalPersistenceFailure_BecomesOutcomeUnknown()
 {var writer=new FakeWriter();var c=await Create(writer,"local-failure",true,repository=>new FailPostedPersistence(repository));var prepared=await c.Service.PrepareAsync(c.InvoiceId);await Assert.ThrowsAsync<PosOutcomeUnknownException>(()=>c.Service.PostAsync(c.InvoiceId,Guid.Parse(prepared.Readiness.PostingId!),"POST TO POS"));Assert.Equal(1,writer.Calls);var status=await c.Service.GetStatusAsync(c.InvoiceId);Assert.Equal(PostingStates.OutcomeUnknown,status.Readiness.State);Assert.Contains(status.Readiness.Blockers,x=>x.Contains("unknown outcome",StringComparison.OrdinalIgnoreCase));}
 [Fact] public async Task StartupRecovery_NeverReplaysInterruptedPosting()
 {var writer=new FakeWriter();var c=await Create(writer,"startup-recovery");var prepared=await c.Service.PrepareAsync(c.InvoiceId);var id=Guid.Parse(prepared.Readiness.PostingId!);Assert.NotNull(await c.Postings.TryStartAsync(id,DateTimeOffset.UtcNow));await c.Service.InitializeAsync();await c.Service.InitializeAsync();var status=await c.Service.GetStatusAsync(c.InvoiceId);Assert.Equal(PostingStates.OutcomeUnknown,status.Readiness.State);Assert.Equal(0,writer.Calls);Assert.Single(await c.Postings.ListEventsAsync(id),x=>x.EventType==PostingRecoveryEventTypes.StartupInterruptedAttempt);}
 private async Task<Context> Create(IPosWriteGateway writer,string suffix="default",bool schemaValid=true,
  Func<IInvoicePostingRepository,IInvoicePostingRepository>? decorateRepository=null)
 {var root=Path.Combine(dir,suffix);var paths=new ApplicationPaths(root);var factory=new SqliteConnectionFactory(paths);await new SqliteDatabaseInitializer(paths,factory,NullLogger<SqliteDatabaseInitializer>.Instance).InitializeAsync();var invoiceRepo=new InvoiceRepository(factory);var invoiceService=new InvoiceService(paths,invoiceRepo,Options.Create(new StockSyncOptions()),NullLogger<InvoiceService>.Instance);var invoice=(await invoiceService.UploadAsync(new MemoryStream(Encoding.ASCII.GetBytes("%PDF-1.7\noriginal\n%%EOF")),"i.pdf",Guid.NewGuid().ToString("D"))).Invoice;var extractions=new InvoiceExtractionRepository(factory);await extractions.TryBeginAsync(invoice.Id,DateTimeOffset.UtcNow);var json=JsonSerializer.Serialize(InvoiceExtractionServiceTests.SampleData(),new JsonSerializerOptions(JsonSerializerDefaults.Web));await extractions.CompleteAsync(invoice.Id,InvoiceExtractionRecord.SucceededStatus,json,DateTimeOffset.UtcNow);var fingerprint=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(json))).ToLowerInvariant();var now=DateTimeOffset.UtcNow;var line=new InvoiceReviewLine(Guid.NewGuid(),0,"Medicine 10mg x20","2","20","500",null,ReviewDecisionSources.ManualSelection,"MED-1","Medicine 10mg x20",null,100,[],2,20,500,40,12.5m,null,true,[],now,now);var reviewRepo=new InvoiceReviewRepository(factory);await reviewRepo.SaveAsync(new(invoice.Id,fingerprint,ReviewStatuses.ReadyForNextPhase,[line],now,now,"Supplier Ltd"));var postingRepo=new InvoicePostingRepository(factory);var postingStore=decorateRepository?.Invoke(postingRepo)??postingRepo;var schemaResult=schemaValid?new PosSchemaValidationResult(true,true,[],[],now,SchemaSnapshot()):new PosSchemaValidationResult(false,false,["POS writes are disabled."],[],now);var service=new InvoicePostingService(invoiceService,reviewRepo,extractions,postingStore,new FakePos(),new FakeSchema(schemaResult),writer,new PostingRetryPolicy(),NullLogger<InvoicePostingService>.Instance);return new(invoice.Id,service,extractions,reviewRepo,postingStore);}
 private static PosSchemaSnapshot SchemaSnapshot(){var cols=new List<PosColumnMetadata>();void Add(string t,string type,params string[] names){foreach(var n in names)cols.Add(new(t,n,type,200,18,4,true,false,false));}Add("addpro","nvarchar","proname","procat","pro_barcode");Add("addpro","decimal","proprice","pro_discount");Add("stockin","nvarchar","proname","pro_barcode","proexpiry");Add("stockin","decimal","procost","proprice");return new([],cols,true,true,DateTimeOffset.UtcNow);}
 public void Dispose(){Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(Directory.Exists(dir))Directory.Delete(dir,true);}
 private sealed record Context(Guid InvoiceId,IInvoicePostingService Service,IInvoiceExtractionRepository Extractions,IInvoiceReviewRepository Reviews,IInvoicePostingRepository Postings);
 private sealed class FakeSchema(PosSchemaValidationResult result):IPosSchemaValidator{public Task<PosSchemaValidationResult> ValidateAsync(CancellationToken t=default)=>Task.FromResult(result);}
 private sealed class FakeWriter:IPosWriteGateway{public int Calls;public Exception? Error;public Task<PosPostingResult> PostAsync(PostingSnapshot s,CancellationToken t=default){Calls++;return Error is null?Task.FromResult(new PosPostingResult([],s.Lines.Count,DateTimeOffset.UtcNow)):Task.FromException<PosPostingResult>(Error);}}
 private sealed class BlockingWriter:IPosWriteGateway{public int Calls;public TaskCompletionSource Started{get;}=new(TaskCreationOptions.RunContinuationsAsynchronously);public TaskCompletionSource Release{get;}=new(TaskCreationOptions.RunContinuationsAsynchronously);public async Task<PosPostingResult> PostAsync(PostingSnapshot s,CancellationToken t=default){Calls++;Started.SetResult();await Release.Task.WaitAsync(t);return new([],s.Lines.Count,DateTimeOffset.UtcNow);}}
 private sealed class FailPostedPersistence(IInvoicePostingRepository inner):IInvoicePostingRepository
 {private bool failed;public Task<InvoicePostingRecord?> GetAsync(Guid invoiceId,string fingerprint,CancellationToken token=default)=>inner.GetAsync(invoiceId,fingerprint,token);public Task<InvoicePostingRecord?> GetByIdAsync(Guid id,CancellationToken token=default)=>inner.GetByIdAsync(id,token);public Task<IReadOnlyList<InvoicePostingRecord>> ListAsync(Guid invoiceId,CancellationToken token=default)=>inner.ListAsync(invoiceId,token);public Task<InvoicePostingRecord> PrepareAsync(Guid invoiceId,string fingerprint,string snapshot,DateTimeOffset now,CancellationToken token=default)=>inner.PrepareAsync(invoiceId,fingerprint,snapshot,now,token);public Task<PostingAttemptRecord?> TryStartAsync(Guid id,DateTimeOffset now,CancellationToken token=default)=>inner.TryStartAsync(id,now,token);public Task<StartupRecoveryResult> RecoverInterruptedAsync(DateTimeOffset now,CancellationToken token=default)=>inner.RecoverInterruptedAsync(now,token);public Task<IReadOnlyList<PostingAttemptRecord>> ListAttemptsAsync(Guid id,CancellationToken token=default)=>inner.ListAttemptsAsync(id,token);public Task<IReadOnlyList<PostingRecoveryEventRecord>> ListEventsAsync(Guid id,CancellationToken token=default)=>inner.ListEventsAsync(id,token);public Task<IReadOnlyList<PostingReconciliationDecisionRecord>> ListDecisionsAsync(Guid id,CancellationToken token=default)=>inner.ListDecisionsAsync(id,token);public Task AppendRecoveryInspectionAsync(Guid id,Guid requestId,string message,DateTimeOffset now,CancellationToken token=default)=>inner.AppendRecoveryInspectionAsync(id,requestId,message,now,token);public Task<PostingReconciliationDecisionRecord> RecordDecisionAsync(Guid id,Guid requestId,string decision,string note,DateTimeOffset now,CancellationToken token=default)=>inner.RecordDecisionAsync(id,requestId,decision,note,now,token);public Task SetOutcomeAsync(Guid id,string state,string? error,string? result,DateTimeOffset? confirmed,DateTimeOffset now,CancellationToken token=default){if(state==PostingStates.Posted&&!failed){failed=true;throw new IOException("simulated local persistence failure");}return inner.SetOutcomeAsync(id,state,error,result,confirmed,now,token);}}
 private sealed class FakePos:IPointOfSaleGateway{public bool IsConfigured=>true;public Task VerifyConnectionAsync(CancellationToken t=default)=>Task.CompletedTask;public Task<IReadOnlyList<PosProductDto>> GetProductsAsync(CancellationToken t=default)=>Task.FromResult<IReadOnlyList<PosProductDto>>([new("MED-1","Medicine 10mg x20",null,null,null,"123",null)]);public Task<IReadOnlyList<PosVendorDto>> GetVendorsAsync(CancellationToken t=default)=>Task.FromResult<IReadOnlyList<PosVendorDto>>([new("Supplier Ltd")]);public Task<IReadOnlyList<PosCategoryDto>> GetCategoriesAsync(CancellationToken t=default)=>Task.FromResult<IReadOnlyList<PosCategoryDto>>([new("Tablets")]);}
}
